-- ============================================================
-- Quiz coverage for Phase 3 batch 5 (Cloud -- Azure Identity &
-- Compute): cloud/azure, cloud/azure-entra, cloud/azure-vms.
--
-- cloud/azure (overview, fundamentals, intermediate) -- 15 questions.
-- cloud/azure-entra (overview, fundamentals, intermediate, advanced) -- 20 questions.
-- cloud/azure-vms (overview, fundamentals, intermediate, advanced) -- 20 questions.
-- Total: 55 questions.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- cloud/azure/overview ----------
('cloud', 'azure', 'overview', 'What is the correct order of Azure''s resource hierarchy, from broadest to narrowest?', '["Subscriptions -> Management Groups -> Resource Groups -> Resources", "Management Groups -> Subscriptions -> Resource Groups -> Resources", "Resource Groups -> Subscriptions -> Management Groups -> Resources", "Management Groups -> Resource Groups -> Subscriptions -> Resources"]', 1, 'Management Groups apply org-wide policy/RBAC across many Subscriptions; Subscriptions are the billing/quota boundary; Resource Groups are lifecycle containers within a subscription; Resources are the individual objects inside a Resource Group.', 'beginner'),
('cloud', 'azure', 'overview', 'What does Azure Resource Manager (ARM) actually do?', '["It is one specific deployment tool that competes with the Azure Portal and CLI", "It is the single control-plane API that the Portal, CLI, Terraform, and Bicep all call underneath -- every Azure interaction ultimately goes through it", "It only manages virtual machines, not other resource types", "It is a billing-only service with no effect on resource state"]', 1, 'Because every tool goes through the same ARM API, there is exactly one source of truth for a resource''s actual state, regardless of which tool made the change.', 'beginner'),
('cloud', 'azure', 'overview', 'Why is Managed Identity generally preferred over a service principal with a stored password for workload authentication?', '["Managed Identity is faster at runtime", "Azure manages the underlying credential''s creation and rotation automatically, so there is no secret value for the application''s code to hold or leak", "Service principals cannot be assigned any RBAC roles", "Managed Identity works outside of Azure, unlike service principals"]', 1, 'A service principal with a stored secret is a credential that can leak from a config file or repository; a Managed Identity is tied directly to the resource''s own lifecycle with no secret for code to hold.', 'intermediate'),
('cloud', 'azure', 'overview', 'What is the practical difference between an Azure region and an Availability Zone?', '["They are two names for the same concept", "A region is a geographic area containing one or more data centers; an Availability Zone is a physically separate, independently-powered facility within a region -- deploying across zones (not just across VMs in one zone) protects against a single data-center failure", "Availability Zones span multiple regions", "Regions only exist for compliance purposes and have no effect on architecture"]', 1, 'Not every Azure region has availability zones, so zone-redundant deployment availability should be checked per target region rather than assumed.', 'intermediate'),
('cloud', 'azure', 'overview', 'In the AKS node pool model referenced in this overview, what is the purpose of separating system and user node pools?', '["System node pools run application workloads and user node pools run cluster components", "System node pools run cluster-critical components so a resource-hungry application workload cannot starve them of capacity, while user node pools run the actual application workloads and can be scaled/configured independently", "There is no functional difference; the split is purely cosmetic", "User node pools are only used during cluster upgrades"]', 1, 'Keeping cluster-critical components isolated from application workloads means an application spike cannot degrade the cluster''s own control-plane-supporting agents.', 'intermediate'),

-- ---------- cloud/azure/fundamentals ----------
('cloud', 'azure', 'fundamentals', 'What is the standard convention for deciding which resources belong in the same Azure Resource Group?', '["Resources should be grouped alphabetically by name", "Resources that share the same lifecycle -- created and deleted together -- belong in the same Resource Group, since deleting a Resource Group deletes everything inside it", "All resources in a subscription should go into a single default Resource Group", "Resource Groups should contain exactly one resource each"]', 1, 'Deleting a Resource Group deletes everything inside it, which is exactly why lifecycle (not resource type or team) is the grouping principle that matters.', 'beginner'),
('cloud', 'azure', 'fundamentals', 'At what levels can an Azure RBAC role assignment be scoped?', '["Only at the subscription level", "At any level of the hierarchy -- Management Group, Subscription, Resource Group, or an individual Resource", "Only at the individual resource level", "Role assignments cannot be scoped; they always apply account-wide"]', 1, 'A role granted at the subscription level applies to every resource within it; a role granted at a specific resource applies only there -- over-scoping a role assignment is a common real source of unintended access.', 'intermediate'),
('cloud', 'azure', 'fundamentals', 'Why are resource tags described as a "low-effort habit that pays off constantly later"?', '["Tags automatically encrypt resources", "Tags are the practical mechanism for cost allocation reporting, automated policy enforcement, and filtering resources at scale -- and establishing a convention before resources sprawl is far cheaper than retrofitting tags later", "Tags are required by Azure before a resource can be created", "Tags replace the need for Resource Groups entirely"]', 1, 'Once hundreds of resources exist without tags, retrofitting a tagging convention is a much larger effort than establishing one from the start.', 'beginner'),
('cloud', 'azure', 'fundamentals', 'What does the fundamentals section identify as the reason two different Azure tools (e.g. the Portal and Terraform) always agree on a resource''s actual state?', '["They poll each other periodically to stay in sync", "Both ultimately call the same underlying ARM API, so there is one source of truth rather than one per tool", "Azure caches state separately for each tool and reconciles it nightly", "They do not always agree -- this is a known limitation"]', 1, 'Because ARM is the single control-plane API underneath every tool, there is exactly one source of truth for what a resource''s state actually is.', 'intermediate'),
('cloud', 'azure', 'fundamentals', 'Per this section, what should be checked before assuming zone-redundant deployment is available in a given Azure region?', '["Nothing -- all Azure regions have availability zones", "Whether that specific region actually has Availability Zones, since not every region does", "Only whether the subscription has a Premium support plan", "Whether the VM series being used supports zones, which is independent of the region"]', 1, 'Not every Azure region has availability zones -- confirming zone support for the target region is a prerequisite before designing a zone-redundant architecture.', 'intermediate'),

-- ---------- cloud/azure/intermediate ----------
('cloud', 'azure', 'intermediate', 'What is the key tradeoff between Azure CNI and Kubenet for AKS pod networking?', '["Kubenet gives pods real, routable VNet IPs while Azure CNI does not", "Azure CNI gives every pod a real, routable IP directly from the VNet''s address space (better for enterprise networking integrations) at the cost of consuming meaningfully more IP address space than Kubenet, which uses a separate NAT''d internal range", "There is no networking difference between the two; only the billing model differs", "Kubenet is only available on Windows node pools"]', 1, 'Azure CNI''s direct VNet IP assignment enables Network Policies and on-prem connectivity but requires careful VNet CIDR sizing, since running out of pod IPs mid-cluster-lifecycle is disruptive to fix.', 'intermediate'),
('cloud', 'azure', 'intermediate', 'What distinguishes Application Gateway from a basic Layer 4 load balancer?', '["Application Gateway can only route based on IP:port, same as an L4 load balancer", "Application Gateway operates at Layer 7, routing on URL path/host header/cookies, and includes an integrated Web Application Firewall (WAF) for OWASP-rule-based protection at the edge", "Application Gateway cannot be used with AKS", "Application Gateway only works for HTTPS traffic, never plain HTTP"]', 1, 'The WAF inspects and can block common attack patterns like SQL injection and XSS before traffic ever reaches application pods, which a plain L4 load balancer cannot do.', 'intermediate'),
('cloud', 'azure', 'intermediate', 'What does a Private Endpoint provide that a public endpoint with firewall rules does not?', '["Lower cost for the same PaaS service", "A private IP address from your own VNet for the specific PaaS resource, so traffic never leaves Azure''s private backbone network at all -- the public-endpoint-plus-firewall approach still traverses the public internet", "Automatic encryption of data at rest", "The ability to skip RBAC role assignments entirely"]', 1, 'Even with strict firewall rules, a public endpoint''s traffic path still crosses the public internet; a Private Endpoint removes that path entirely by using a private VNet IP.', 'advanced'),
('cloud', 'azure', 'intermediate', 'What is KQL primarily used for in Azure operations?', '["Provisioning new Azure resources declaratively", "Querying Log Analytics and Application Insights data -- structurally similar to SQL (filtering, aggregation, grouping) but with its own pipe-based (|) syntax", "Defining RBAC role assignments", "Writing Azure Resource Manager templates"]', 1, 'Kusto Query Language (KQL) fluency directly determines how fast an incident can actually be investigated using Azure Monitor''s log data, compared to relying on the Portal''s UI-based filters alone.', 'intermediate'),
('cloud', 'azure', 'intermediate', 'How does Conditional Access differ from basic Azure RBAC?', '["They are the same mechanism with different names", "RBAC defines permissions once a session is authenticated; Conditional Access determines the conditions under which authentication itself is allowed to succeed, or what additional verification it requires, based on real-time signals", "Conditional Access replaces the need for RBAC entirely", "RBAC only applies to Entra ID, while Conditional Access only applies to Azure resources"]', 1, 'RBAC governs what an authenticated identity can do; Conditional Access governs whether/how that identity is allowed to authenticate in the first place, based on context like location, device state, or risk signals.', 'advanced'),

-- ---------- cloud/azure-entra/overview ----------
('cloud', 'azure-entra', 'overview', 'What is the relationship between Entra ID and Azure RBAC?', '["They are the same service under two different names", "Entra ID authenticates (confirms who is making a request); Azure RBAC authorizes (determines what that authenticated identity can actually do, and where) -- they are two separate layers working together", "RBAC handles authentication and Entra ID handles authorization", "Azure RBAC only works for human users, never for applications"]', 1, 'Authentication and authorization are two genuinely separate questions: Entra ID answers "who is this?" and Azure RBAC answers "what can they do, and where?"', 'beginner'),
('cloud', 'azure-entra', 'overview', 'What is a Managed Identity, conceptually?', '["A password vault shared across an Entra ID tenant", "An automatically managed identity tied to an Azure resource''s own lifecycle, requiring no stored credentials for that resource to authenticate to other Azure services", "A type of Conditional Access policy", "A synonym for an Entra ID Group"]', 1, 'Because the identity is tied directly to the resource''s lifecycle, there is no secret value for an application''s code to hold, unlike a service principal with a stored password.', 'beginner'),
('cloud', 'azure-entra', 'overview', 'What does Privileged Identity Management (PIM) fundamentally change about how privileged roles are used?', '["It grants every admin permanent standing access for convenience", "It replaces standing (always-on) privileged access with just-in-time activation -- users request elevation, it is time-bound, and every activation is logged", "It removes the need for MFA on admin roles", "It only applies to Reader-level roles, not Owner or Global Administrator"]', 1, 'JIT access reduces the attack surface (no standing admin access to compromise) and produces an audit trail of who elevated privileges and when.', 'intermediate'),
('cloud', 'azure-entra', 'overview', 'In a Role Assignment, what three things does Azure RBAC combine?', '["A username, a password, and an MFA method", "A security principal (user/group/service principal/managed identity), a role (defining allowed actions), and a scope (where in the hierarchy it applies)", "A resource group, a region, and a subscription tier", "A tenant ID, a client ID, and a client secret"]', 1, 'Role Assignment = Principal + Role + Scope -- this is the structural model underlying every Azure RBAC grant, whatever the specific role or scope chosen.', 'intermediate'),
('cloud', 'azure-entra', 'overview', 'Why does Conditional Access commonly get configured in "report-only" mode before enforcement?', '["Report-only mode is required by Microsoft licensing", "It lets an administrator see who WOULD have been blocked or challenged by a policy, without actually enforcing it, catching unintended lockouts before they happen", "Report-only mode is a permanent alternative to enforcing policies at all", "It disables MFA temporarily while the policy is tested"]', 1, 'Rolling out via report-only -> pilot group -> full enforcement is the safe staged approach, since an untested policy enforced tenant-wide can lock out legitimate users.', 'advanced'),

-- ---------- cloud/azure-entra/fundamentals ----------
('cloud', 'azure-entra', 'fundamentals', 'What is the correct sequence of steps to grant a VM keyless access to a Key Vault secret via Managed Identity?', '["Create a service principal, generate a client secret, store it in the VM''s config", "Enable a system-assigned managed identity on the VM, retrieve its principal/object ID, then grant that identity access on the Key Vault (via an access policy or an RBAC role assignment)", "Grant Key Vault access directly to the VM''s name; no identity is needed", "Store the Key Vault''s master key inside the VM''s custom data script"]', 1, 'The identity itself has no password -- the VM''s SDK code uses ManagedIdentityCredential to obtain a short-lived token for whatever access has been separately granted to that identity''s object ID.', 'intermediate'),
('cloud', 'azure-entra', 'fundamentals', 'What is a Service Principal, in relation to an App Registration?', '["They are unrelated concepts", "A Service Principal is the tenant-specific instance of an App Registration -- an App Registration can have a Service Principal in each tenant that uses it", "A Service Principal always requires a Managed Identity to function", "An App Registration is created automatically whenever a user account is created"]', 1, 'One App Registration (the app''s identity definition) can result in multiple Service Principals if the app is used across multiple tenants -- each tenant gets its own instance.', 'intermediate'),
('cloud', 'azure-entra', 'fundamentals', 'In Azure RBAC scoping, what happens to a role assigned at the subscription level?', '["It applies only to resources directly inside the subscription object itself, not to any Resource Group", "It applies to every Resource Group and Resource beneath that subscription, unless narrowed at a lower scope", "It has no effect until also assigned separately at each Resource Group", "Subscription-level role assignments are not supported in Azure"]', 1, 'Scope inherits downward through the hierarchy -- a broad role at a high scope applies everywhere beneath it, which is exactly why over-scoping is a common real source of excess access.', 'intermediate'),
('cloud', 'azure-entra', 'fundamentals', 'What does a custom Azure role definition''s "Actions" list actually define?', '["The users who are allowed to assume the role", "The specific management-plane operations (e.g. Microsoft.Compute/virtualMachines/restart/action) that the role grants when assigned", "The Conditional Access policies that apply to the role", "The billing tier associated with the role"]', 1, 'A custom role''s Actions array is a least-privilege mechanism -- e.g. a "VM Restart Operator" role can be scoped to only the restart and read actions, nothing broader.', 'advanced'),
('cloud', 'azure-entra', 'fundamentals', 'Why is a Managed Identity described as more secure than a hidden "spare key under the doormat"?', '["Because Managed Identity credentials are stored encrypted in the application''s own config file", "Because there is no persistent credential value at all for anyone to find -- the identity is issued and tied to the resource automatically, and access can be revoked the instant the resource is deleted", "Because Managed Identity requires a physical hardware key", "Because Managed Identity credentials never expire, unlike passwords"]', 1, 'A stored service-principal secret is a static value that can be found/leaked, similar to a spare key under a doormat; a Managed Identity has no equivalent static value to find in the first place.', 'beginner'),

-- ---------- cloud/azure-entra/intermediate ----------
('cloud', 'azure-entra', 'intermediate', 'Why does Entra ID recommend excluding a break-glass account from every Conditional Access policy?', '["Break-glass accounts are exempt from Azure billing", "If every account (including admin accounts) is subject to a Conditional Access policy that misfires, there needs to be at least one account still able to sign in to fix the misconfiguration", "Break-glass accounts are only used during initial tenant setup and never again", "Excluding an account from policies is required by Microsoft licensing terms"]', 1, 'A break-glass account is the safety net against a Conditional Access policy locking out every admin simultaneously -- it should use strong, non-MFA-dependent credentials stored securely outside Entra ID.', 'advanced'),
('cloud', 'azure-entra', 'intermediate', 'What is dynamic group membership in Entra ID?', '["A group whose membership must be manually updated by an administrator daily", "A group whose membership is automatically computed from a rule (e.g. user.department -eq \\"Engineering\\"), updating automatically as user attributes change", "A group that only exists for the duration of a single sign-in session", "A synonym for a Conditional Access named location"]', 1, 'Because membership is rule-driven, users are added or removed automatically as their attributes (department, job title, license) change, without manual group management.', 'intermediate'),
('cloud', 'azure-entra', 'intermediate', 'When creating a service principal via `az ad sp create-for-rbac` for CI/CD use, what does this batch''s content recommend as the preferred alternative wherever possible?', '["A shared human user account with a saved password", "Managed Identity, since it requires no stored client secret and only works for Azure-native resources/services", "A hardcoded API key embedded in the pipeline YAML", "Disabling authentication entirely for internal pipelines"]', 1, 'The batch content explicitly frames Managed Identity as preferred over a service principal with a client secret, precisely because the latter is a credential that must be stored, rotated, and can leak.', 'intermediate'),
('cloud', 'azure-entra', 'intermediate', 'What are the two key components of a Conditional Access policy, per this section''s framing?', '["Assignments (who/what/where) and Access controls (what to enforce)", "Only a list of blocked IP addresses", "A single Boolean flag: MFA required or not required", "A billing scope and a resource scope"]', 1, 'Assignments determine who/what apps/under what conditions the policy applies; Access controls determine what is then enforced (grant-level controls like requiring MFA, or session-level controls like sign-in frequency).', 'intermediate'),
('cloud', 'azure-entra', 'intermediate', 'What is the practical risk of granting a service principal a client secret via `az ad app credential reset`?', '["The command fails unless MFA is configured first", "The returned password is shown only once and, if lost or leaked, represents a long-lived credential that must be tracked, rotated, and secured -- unlike Managed Identity''s auto-rotated, no-storage-needed model", "Client secrets automatically expire after 24 hours with no way to extend them", "Service principals cannot be granted RBAC roles once a secret is generated"]', 1, 'This is exactly the risk Managed Identity is designed to eliminate -- a client secret is a real, storable, leakable value, while a managed identity''s token issuance requires no equivalent stored secret.', 'advanced'),

-- ---------- cloud/azure-entra/advanced ----------
('cloud', 'azure-entra', 'advanced', 'In PIM terminology, what is the difference between an "eligible" and an "active" role assignment?', '["They are identical; the terms are interchangeable", "An eligible assignment lets a user activate the role only when needed (time-bound, with justification/MFA/approval); an active assignment grants the role permanently, which PIM recommends avoiding for highly privileged roles", "Active assignments require no MFA, while eligible assignments always require MFA", "Eligible assignments can only be granted to groups, never individual users"]', 1, 'The whole point of PIM is shifting privileged roles from standing (active) assignments to just-in-time (eligible) ones, minimizing the window during which a compromised account holds elevated rights.', 'advanced'),
('cloud', 'azure-entra', 'advanced', 'What capability does Continuous Access Evaluation (CAE) add to Conditional Access?', '["It removes the need for Conditional Access policies entirely", "Near real-time revocation of access when a critical event occurs (e.g. a user account is disabled or a high sign-in risk is detected), rather than waiting for the existing token to naturally expire", "It only applies to legacy authentication protocols like SMTP", "It automatically approves all PIM activation requests"]', 1, 'Without CAE, a previously-issued access token could remain valid for its full lifetime even after a critical signal (like account disablement) occurs; CAE closes that gap.', 'advanced'),
('cloud', 'azure-entra', 'advanced', 'What distinguishes the "Client Credentials" OAuth 2.0 flow from "Authorization Code + PKCE"?', '["Client Credentials is used for service-to-service auth with no user context; Authorization Code + PKCE is for web/SPA apps acting on behalf of a signed-in user", "They are the same flow with different names for the same use case", "PKCE is only relevant to native mobile apps, never web apps", "Client Credentials requires a signed-in user, while Authorization Code does not"]', 1, 'Client Credentials is the right choice when there is no human user involved at all (a backend service calling another service); Authorization Code + PKCE is the recommended flow when a user is actually signing in.', 'advanced'),
('cloud', 'azure-entra', 'advanced', 'What is the difference between "Delegated" and "Application" API permissions on an App Registration?', '["Delegated permissions act on behalf of a signed-in user; Application permissions are for an unattended background service with no user context and require admin consent", "Delegated permissions never require any consent at all", "Application permissions are always weaker than Delegated permissions", "The two permission types are functionally identical, differing only in display name"]', 1, 'Because Application permissions have no user to attribute an action to, they carry higher risk and Microsoft requires explicit admin consent before they can be used.', 'advanced'),
('cloud', 'azure-entra', 'advanced', 'Why does this content recommend using Azure RBAC role assignments on a Key Vault instead of the legacy vault-access-policy model where possible?', '["Legacy access policies are being phased out in favor of Azure''s unified RBAC-based permission model for consistency with how permissions work elsewhere in Azure -- exact current Microsoft guidance should still be checked before relying on this", "Access policies are faster to configure than RBAC role assignments", "RBAC role assignments cannot grant Key Vault secret read access at all", "Legacy access policies do not support Managed Identity as a principal"]', 0, 'This is flagged as a needs-verification item in the batch content precisely because Azure''s recommended default for Key Vault permissions has been evolving toward RBAC -- worth confirming against current Microsoft docs rather than assuming either model is definitively "correct."', 'advanced'),

-- ---------- cloud/azure-vms/overview ----------
('cloud', 'azure-vms', 'overview', 'What is the practical difference between an Availability Set and an Availability Zone for VM placement?', '["They are the same mechanism under two names", "An Availability Set spreads VMs across fault/update domains within ONE datacenter; an Availability Zone spreads VMs across physically separate datacenters within a region, offering stronger protection against a datacenter-level failure", "Availability Zones are only usable with VM Scale Sets, never standalone VMs", "Availability Sets provide stronger protection than Availability Zones"]', 1, 'An Availability Set protects against rack-level hardware failure and planned maintenance within a single datacenter; only spreading VMs across zones protects against losing an entire datacenter.', 'beginner'),
('cloud', 'azure-vms', 'overview', 'What kind of workload are Azure Spot VMs best suited for?', '["Anything requiring guaranteed, uninterrupted uptime, like a primary database", "Batch, CI/CD, and other fault-tolerant workloads that can tolerate being evicted with short notice when Azure needs the capacity back", "Long-running stateful services that cannot be restarted", "Workloads requiring a fixed, guaranteed hourly price with no eviction risk"]', 1, 'Spot VMs offer a discount in exchange for no uptime guarantee -- Azure can reclaim the capacity with short notice, which only fits workloads designed to handle interruption gracefully.', 'intermediate'),
('cloud', 'azure-vms', 'overview', 'What is the main advantage of Azure Bastion over exposing a VM''s SSH/RDP port directly to the internet?', '["Bastion makes the VM boot faster", "Bastion provides SSH/RDP access over HTTPS through the Azure Portal or CLI without requiring the target VM to have a public IP address at all", "Bastion is required before a VM can join a VNet", "Bastion replaces the need for Network Security Groups"]', 1, 'Removing the public IP (and the open SSH/RDP port that would otherwise need one) removes an entire class of internet-facing attack surface from the VM.', 'intermediate'),
('cloud', 'azure-vms', 'overview', 'Which managed disk tier is designed for databases requiring sub-millisecond latency?', '["Standard HDD", "Ultra Disk", "Standard SSD", "Premium SSD (P-series), always"]', 1, 'Ultra Disk is positioned at the top of Azure''s managed disk tiers specifically for latency-sensitive, high-IOPS workloads like demanding database engines.', 'beginner'),
('cloud', 'azure-vms', 'overview', 'What does enabling a system-assigned Managed Identity on a VM (as shown in the Terraform example) let that VM do?', '["Automatically resize itself based on load", "Authenticate to other Azure services (such as Key Vault) without any stored password, using an identity tied to the VM''s own lifecycle", "Bypass all Network Security Group rules", "Automatically join an Availability Zone"]', 1, 'The VM''s system-assigned identity can be granted RBAC access to another resource, and the VM''s SDK code authenticates using that identity -- no credential is stored anywhere in the VM''s configuration.', 'intermediate'),

-- ---------- cloud/azure-vms/fundamentals ----------
('cloud', 'azure-vms', 'fundamentals', 'What is the key difference between `az vm stop` and `az vm deallocate`?', '["They are functionally identical commands", "`az vm stop` shuts down the OS but Azure still reserves compute capacity for the VM (so compute is STILL billed); `az vm deallocate` fully releases that capacity back to Azure, stopping compute billing", "`az vm deallocate` deletes the VM''s disks permanently", "`az vm stop` is only available for Windows VMs, not Linux"]', 1, 'This distinction is one of the most common early cost mistakes -- assuming a "stopped" VM (without deallocation) has stopped billing when it has not, since the compute capacity is still reserved.', 'beginner'),
('cloud', 'azure-vms', 'fundamentals', 'What can be checked via `az vm get-instance-view` to confirm whether a VM has actually stopped billing for compute?', '["The VM''s name tag", "The PowerState value in the instance view''s statuses -- \\"VM stopped\\" means still reserved/billed, while \\"VM deallocated\\" means compute billing has actually stopped", "The VM''s public IP address", "The resource group''s tag list"]', 1, 'PowerState is the concrete, checkable signal that distinguishes a VM that is merely shut down from one that has actually released its compute allocation.', 'intermediate'),
('cloud', 'azure-vms', 'fundamentals', 'What is the purpose of the Azure Monitor Agent extension shown in this section, replacing the legacy Log Analytics/MMA agent?', '["It resizes the VM automatically based on metrics", "It collects metrics and logs from the VM for observability, as the current recommended monitoring agent for Azure VMs", "It manages the VM''s Managed Identity credentials", "It is only used for Windows VMs, never Linux"]', 1, 'The content explicitly notes this replaces the legacy Log Analytics/MMA agent as Microsoft''s current-generation VM monitoring agent.', 'intermediate'),
('cloud', 'azure-vms', 'fundamentals', 'In a VM Scale Set autoscale rule condition like "Percentage CPU > 70 avg 5m", what does the "avg 5m" portion control?', '["It caps the maximum scale-out to 5 instances", "It defines the time window and aggregation used to evaluate the metric -- the rule triggers based on the average CPU percentage over a rolling 5-minute window, not an instantaneous spike", "It delays the scale-out action by 5 minutes after the rule fires", "It limits the rule to firing only 5 times per hour"]', 1, 'Using an averaged window rather than an instantaneous reading avoids reacting to brief CPU spikes, triggering scale actions only on sustained load changes.', 'advanced'),
('cloud', 'azure-vms', 'fundamentals', 'Why does mixing a comment after a line-continuation backslash (`\\`) break a multi-line Azure CLI command in bash?', '["Bash comments are not supported at all inside any command", "The backslash must be the very last character before the newline for line continuation to work -- text (including a comment) after it means the following line is NOT joined, splitting the command into separate, broken statements", "Comments are only allowed on the first line of a script", "This only breaks PowerShell, not bash"]', 1, 'Bash performs line-continuation by literally requiring a backslash immediately followed by a newline; anything else on that line (like a trailing comment) prevents the join, so the remaining flags run as a separate, invalid command.', 'advanced'),

-- ---------- cloud/azure-vms/intermediate ----------
('cloud', 'azure-vms', 'intermediate', 'What is the minimum recommended subnet size for the dedicated AzureBastionSubnet?', '["Any size works; there is no minimum", "/26, as a dedicated subnet reserved specifically for Azure Bastion", "/16, since Bastion needs a very large address range", "/30, the smallest possible subnet"]', 1, 'Azure Bastion requires its own dedicated subnet named AzureBastionSubnet, sized at least /26, separate from the subnets used by application VMs.', 'intermediate'),
('cloud', 'azure-vms', 'intermediate', 'Why does a VM Scale Set typically need both a "scale out" and a separate "scale in" autoscale rule?', '["Azure only allows one autoscale rule per scale set", "Scaling out (adding instances under load) and scaling in (removing instances when load drops) are two distinct actions, each needing its own metric threshold and cooldown period to avoid oscillating rapidly between the two", "Scale-in is handled automatically without any rule, unlike scale-out", "Scale-in rules are only needed for Windows-based scale sets"]', 1, 'Configuring both with distinct thresholds (e.g. scale out above 70% CPU, scale in below 30%) and cooldowns prevents the scale set from flapping instance count up and down on borderline load.', 'intermediate'),
('cloud', 'azure-vms', 'intermediate', 'What is a Proximity Placement Group used for?', '["Grouping VMs purely for billing purposes", "Co-locating VMs physically close together to minimize network latency between them, useful for latency-sensitive multi-tier applications", "Automatically replicating a VM across multiple regions", "Enforcing a shared Availability Zone across a subscription"]', 1, 'Proximity Placement Groups exist specifically to reduce the network hop distance between VMs that need to communicate with very low latency, such as a tightly coupled compute cluster.', 'advanced'),
('cloud', 'azure-vms', 'intermediate', 'What must happen to a VM before it can be captured as a reusable image in an Azure Compute Gallery?', '["Nothing; any running VM can be captured directly with no preparation", "It must be deallocated and generalized (e.g. via waagent -deprovision + `az vm generalize`) to strip machine-specific identifiers before capture", "It must be resized to the smallest available SKU", "It must be moved into a different subscription first"]', 1, 'Generalizing removes machine-specific state (like the hostname and SID) so the captured image can be safely used as a template for multiple new VM instances.', 'advanced'),
('cloud', 'azure-vms', 'intermediate', 'What does the Azure Instance Metadata Service''s Scheduled Events endpoint provide for a Spot VM?', '["A guarantee that the VM will never be evicted", "Advance warning (commonly cited as around 30 seconds) that the VM is about to be evicted, letting the workload checkpoint or gracefully shut down before it happens", "The VM''s current hourly billing rate", "A list of other VMs in the same Availability Set"]', 1, 'Polling this endpoint is the standard way to build graceful eviction handling into a Spot VM workload -- reacting to the warning before the VM is actually reclaimed, rather than being caught by surprise.', 'advanced'),

-- ---------- cloud/azure-vms/advanced ----------
('cloud', 'azure-vms', 'advanced', 'In the Azure Compute Gallery image-versioning workflow, what is the practical benefit of deploying new VMs from a captured gallery image instead of a stock marketplace image plus a bootstrap script?', '["Gallery images are always cheaper to store than marketplace images", "New VMs boot with software already installed and configured, avoiding the time cost of re-running a full setup/bootstrap script on every new instance", "Gallery images do not require generalization", "Marketplace images cannot be used with VM Scale Sets at all"]', 1, 'A golden image captures the fully-configured state once; every subsequent VM deployed from it skips the setup time a bootstrap script would otherwise need to repeat on each new instance.', 'advanced'),
('cloud', 'azure-vms', 'advanced', 'What does the `--eviction-policy Deallocate` setting control for a Spot VM, compared to `Delete`?', '["Deallocate removes the VM and all its disks permanently; Delete only stops billing temporarily", "Deallocate stops the VM (keeping its disk) when evicted; Delete removes the VM entirely on eviction -- the choice affects whether the VM can simply be restarted later or must be recreated", "Deallocate only applies to VM Scale Sets, never standalone Spot VMs", "Eviction policy has no effect on what happens to the VM''s data"]', 1, 'Choosing Deallocate preserves the disk so the workload can potentially resume later, whereas Delete fully tears the VM down on eviction -- a meaningful architectural choice depending on the workload.', 'advanced'),
('cloud', 'azure-vms', 'advanced', 'What is the purpose of Ultra Disk in the managed disk lineup covered in this section?', '["It is the cheapest disk tier, intended for archival storage", "It is positioned for the most latency- and IOPS-sensitive workloads, such as databases requiring sub-millisecond latency, sitting above Premium SSD v2 in performance", "It replaces the need for any other managed disk type", "It can only be attached to Spot VMs"]', 1, 'Ultra Disk is explicitly the highest-performance managed disk tier discussed, reserved for workloads where even Premium SSD v2''s latency isn''t sufficient.', 'intermediate'),
('cloud', 'azure-vms', 'advanced', 'Why does mixing On-Demand and Spot instances in the same VM Scale Set require explicit eviction-handling logic in the application, rather than relying on the scale set alone?', '["The scale set automatically retries any evicted work with zero application changes needed", "Eviction can happen mid-task with only short advance warning, so the workload itself must checkpoint or requeue in-progress work using the Scheduled Events signal -- the scale set replacing capacity does not recover in-flight state on its own", "Mixed allocation policies are not actually supported by Azure VM Scale Sets", "Spot instances in a scale set cannot be monitored by Azure Monitor"]', 1, 'The scale set can replace lost capacity, but it has no knowledge of what work was in progress on an evicted instance -- that responsibility falls to the application reacting to the eviction warning itself.', 'advanced'),
('cloud', 'azure-vms', 'advanced', 'What is the recommended way to determine whether a mixed Spot/On-Demand fleet is actually saving money compared to an all-On-Demand equivalent?', '["Rely on the generic published Spot discount percentage as a sufficient estimate", "Compare real subscription billing data for the mixed fleet against a same-capacity all-On-Demand deployment, since generic discount percentages do not account for eviction-driven capacity gaps or workload-specific retry costs", "Cost comparison is not possible since Spot pricing is not itemized in Azure billing", "Assume the mixed fleet is always cheaper without measurement, since Spot is always discounted"]', 1, 'A generic discount percentage does not capture real-world effects like eviction frequency or the cost of requeued/retried work, so an actual billing-data comparison is the reliable way to validate savings.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
